import numpy as np
from scipy.optimize import minimize
import os

N = 26

def construct_packing() -> tuple:
    try:
        base_centers = np.loadtxt('storage/episteme/sota_base_centers.txt')
        base_radii = np.loadtxt('storage/episteme/sota_base_radii.txt')
    except Exception:
        return np.array([[0.5, 0.5]] * 26), np.array([0.05] * 26)

    def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
    def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]

    # --- New Multi-Objective Function ---
    def multi_objective(z):
        c, r = z_to_cr(z)
        primary_objective = -np.sum(r)

        # Penalty calculations
        penalty = 0.0
        penalty_weight = 0.1 # Hyperparameter to tune

        slacks = []
        for i in range(N):
            for j in range(i + 1, N):
                dist = np.linalg.norm(c[i] - c[j])
                slack = dist - (r[i] + r[j])
                slacks.append(slack)

        slacks.sort()

        # Penalty for too many pairs with slack < 1e-9 (target is 25)
        slack_tol_1 = 1e-9
        excess_pairs_1 = 0
        for i in range(len(slacks)):
            if slacks[i] < slack_tol_1:
                excess_pairs_1 += 1
        if excess_pairs_1 > 25:
            penalty += (excess_pairs_1 - 25) * penalty_weight

        # Penalty for too many pairs with slack < 1e-8 (target is 15)
        slack_tol_2 = 1e-8
        excess_pairs_2 = 0
        for i in range(len(slacks)):
            if slacks[i] < slack_tol_2:
                excess_pairs_2 += 1
        if excess_pairs_2 > 15:
            penalty += (excess_pairs_2 - 15) * penalty_weight

        return primary_objective + penalty

    # Constraint functions are standard
    def ineq_boundary(z):
        c, r = z_to_cr(z)
        return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
    def ineq_nonoverlap(z):
        c, r = z_to_cr(z)
        diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1))
        iu = np.triu_indices(N, 1); return dist[iu] - (r[iu[0]] + r[iu[1]])
    def _ensure_validity(c, r):
        for _ in range(10):
            v=0
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.linalg.norm(c[i] - c[j]); rad_sum = r[i] + r[j]
                    if dist < rad_sum: v+=1; scale = (dist/rad_sum)*(1.0-1e-9); r[i]*=scale; r[j]*=scale
            if v==0: break
        return c, np.maximum(r, 0)

    # --- SLSQP Optimization ---
    initial_z = cr_to_z(base_centers, base_radii)
    bounds = [(0,1)]*N*2 + [(1e-6, 0.5)]*N
    constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

    # Note: We can't use an analytical Jacobian for the new objective easily, so we let SLSQP approximate it.
    res = minimize(multi_objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 1000, 'ftol': 1e-9})

    if res.success:
        c_res, r_res = z_to_cr(res.x)
        return _ensure_validity(c_res, r_res)
    else:
        return _ensure_validity(base_centers, base_radii)
